const item = $input.item;
const binaryKeys = Object.keys(item.binary ?? {});
if (binaryKeys.length !== 1) {
  throw new Error('Submit exactly one screenshot file.');
}

const screenshotProperty = binaryKeys[0];
const screenshot = item.binary[screenshotProperty];
return [{
  json: {
    screenshotProperty,
    originalFileName: screenshot.fileName || 'screenshot.png',
    mimeType: screenshot.mimeType || 'image/png',
    errorLogs: item.json['Error logs'] || '',
    projectKey: String(item.json['Jira project key'] || '').trim().toUpperCase()
  },
  binary: item.binary
}];

const items = $input.all();
const results = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const property = item.json.screenshotProperty;
  const screenshot = item.binary?.[property];
  if (!screenshot) throw new Error('Screenshot binary data is unavailable.');

  const buffer = await this.helpers.getBinaryDataBuffer(i, property);
  const base64 = buffer.toString('base64');

  results.push({
    json: {
      ...item.json,
      imageDataUrl: `data:${item.json.mimeType};base64,${base64}`
    },
    binary: item.binary
  });
}
return results;

